#include <charconv>
#include <iostream>
#include <string_view>

bool parse_positive(std::string_view text, int& out) {
    int candidate = 0;
    auto [end, ec] = std::from_chars(text.data(), text.data() + text.size(), candidate);
    if (ec != std::errc{} || end != text.data() + text.size() || candidate <= 0) return false;
    out = candidate; return true;
}
int main() { int result = 0; std::cout << std::boolalpha << parse_positive("25", result) << ':' << result << '\n'; }
